return {
    -- HarmonyTaoist [8297]
    ["STR_ID_HarmonyTaoist[8297][Text1]"] = "@STR_COMMON[451]",
    ["STR_ID_HarmonyTaoist[8297][Text2]"] = "I have cast my magic on the Holy Bead and the Heresy Snake Gall! Use the Holy Bead to transform into a Snakeman and challenge the Heresy Leader. Use the Heresy Snake Gall to transform into a Heresy Snakeman to challenge the Snakeman Leader.",
    ["STR_ID_HarmonyTaoist[8297][Text3]"] = "Good. I will cast my magic spell on the Holy Bead and the Heresy Snake Gall! Then you can use it to transform into a Snakeman or a Heresy Snakeman to continue our plan.",
    ["STR_ID_HarmonyTaoist[8297][Text4]"] = "Get a Holy Bead from the Snakeman and a Heresy Snake Gall from the Heresy Snakeman. We need them to pick a fight between the two snake races.",
    ["STR_ID_HarmonyTaoist[8297][Text5]"] = "Listen! We have a plan to pick a fight between the two snake races. Get a Holy Bead from the Snakeman and a Heresy Snake Gall from the Heresy Snakeman. These two items are the key to carry out the plan!",
    ["STR_ID_HarmonyTaoist[8297][Text6]"] = "I have discussed this with Captor Cooke. This will be a big plan!",
    ["STR_ID_HarmonyTaoist[8297][Text7]"] = "Teach Captor Cooke Cloud Riding! We have to help him send the criminals back to Ape City to be punished by the courts!",
    ["STR_ID_HarmonyTaoist[8297][Text8]"] = "Since you have learned the secret of Cloud Riding, you should go teach Captor Cooke how to ride the clouds. We need to help him send the criminals back to Ape City to be punished by the courts!",
    ["STR_ID_HarmonyTaoist[8297][Text9]"] = "You are not a normal person! I knew it at the time when I saw you! See, you mastered the Cloud Riding!",
    ["STR_ID_HarmonyTaoist[8297][Text10]"] = "Go to the cliff closest to Ape City, and chant `Kuh Limb Mah, Kuh Limb Mah` to use the skill! Don`t forget to put away your weapons, first!",
    ["STR_ID_HarmonyTaoist[8297][Text11]"] = "According to the Scroll, you need a pure mind to fly over the cliff. Now, put down your weapon. Go to the cliff closest to Ape City, and chant `Kuh Limb Mah, Kuh Limb Mah` to use the skill!",
    ["STR_ID_HarmonyTaoist[8297][Text12]"] = "@STR_COMMON[14]",
    ["STR_ID_HarmonyTaoist[8297][Text13]"] = "That is it! The Cloud Riding Scroll. It`s written in the Snakemen`s language... Give it to me. I will translate it to you!",
    ["STR_ID_HarmonyTaoist[8297][Text14]"] = "Snakeman has a secret skill of Cloud Riding. As the name suggested, you can raid the cloud flying over the cliffs. Get a Cloud Riding Scroll from the Snakeman and you will know how to fly!",
    ["STR_ID_HarmonyTaoist[8297][Text15]"] = "A shortcut to Ape City? There is one. Fly over the cliff, and there you go! But you`ll need the Cloud Riding Skill to help you!",
    ["STR_ID_HarmonyTaoist[8297][Text16]"] = "I can`t believe it! You made it! Here are your rewards!",
    ["STR_ID_HarmonyTaoist[8297][Text17]"] = "Slay 50 Snakemen L63 for me! Be careful! They are very aggressive!",
    ["STR_ID_HarmonyTaoist[8297][Text18]"] = "The Snakeman L63 is the most aggressive snake race! I want you to slay 50 Snakemen L63 for me!",
    ["STR_ID_HarmonyTaoist[8297][Text19]"] = "Thank you very much for slaying the Snakeman for me. Here are your rewards!",
    ["STR_ID_HarmonyTaoist[8297][Text20]"] = "Slay 60 Snakeman to return peace to Ape City!",
    ["STR_ID_HarmonyTaoist[8297][Text21]"] = "Snakeman is a bane on Ape City! I want you to slay 60 Snakeman and return peace to Ape City!",
